mapper.select:
SELECT m.* , u.name sendUserName, n.notice_title, n.notice_sent_time noticeSentTime, n.category, u1.name receiveUserName, n.href, n.notice_content FROM blade_biz_notice_message m left join blade_biz_notice n on m.notice_id = n.id LEFT JOIN (SELECT id,name from blade_user )u on m.send_user_id = u.id LEFT JOIN (SELECT id,name from blade_user )u1 on m.receive_user_id = u1.id WHERE n.is_deleted =0
and m.send_user_id = #{noticeCondition.sendUserId}
and n.notice_title like concat(concat('%', #{noticeCondition.noticeTitle}), '%')
and m.receive_user_id = #{noticeCondition.receiveUserId}
and n.category = #{noticeCondition.category}
and m.notice_read_status = #{noticeCondition.noticeReadStatus}
and n.notice_sent_time between #{noticeCondition.firstTime} and #{noticeCondition.endTime}
order by n.notice_sent_time desc

SELECT n.id notice_id, n.notice_title, n.notice_sent_time noticeSentTime, n.category, n.href, n.notice_content, m.messageCount, m.noticeReplyTime, u.name sendUserName FROM blade_biz_notice n LEFT JOIN ( SELECT count(*) messageCount, max( notice_reply_time ) noticeReplyTime, notice_id FROM blade_biz_notice_message GROUP BY notice_id ) m ON m.notice_id = n.id LEFT JOIN ( SELECT count(*) userMessageCount, notice_id FROM blade_biz_notice_message
where receive_user_id = #{noticeCondition.receiveUserId}
GROUP BY notice_id ) m1 ON m1.notice_id = n.id LEFT JOIN (SELECT id,name from blade_user )u on n.create_user = u.id WHERE n.is_deleted =0
and n.create_user = #{noticeCondition.sendUserId}
and n.notice_title like concat(concat('%', #{noticeCondition.noticeTitle}), '%')
and m1.userMessageCount > 0
and n.category = #{noticeCondition.category}
and n.notice_sent_time between #{noticeCondition.firstTime} and #{noticeCondition.endTime}
order by n.notice_sent_time desc

SELECT m.* , n.notice_title, n.notice_sent_time noticeSentTime, n.category, u1.name receiveUserName, n.href, n.notice_content FROM blade_biz_notice_message m left join blade_biz_notice n on m.notice_id = n.id LEFT JOIN (SELECT id,name from blade_user )u1 on m.receive_user_id = u1.id WHERE n.is_deleted =0
and m.send_user_id = #{noticeCondition.sendUserId}
and m.notice_id = #{noticeCondition.noticeId}
and n.notice_title like concat(concat('%', #{noticeCondition.noticeTitle}), '%')
and m.receive_user_id = #{noticeCondition.receiveUserId}
and n.category = #{noticeCondition.category}
and m.notice_read_status = #{noticeCondition.noticeReadStatus}
and n.notice_sent_time between #{noticeCondition.firstTime} and #{noticeCondition.endTime}
order by n.notice_sent_time desc

select u.* from blade_user u left join blade_group_user g  on u.id = g.user_id where u.is_deleted=0

    and g.group_id = #{groupId}


    and (u.real_name like  concat('%',#{userName}, '%') or u.account like  concat('%',#{userName} , '%') or u.name like  concat('%',#{userName} , '%'))
